```python
import pandas as pd
import pyopencl as cl
import numpy as np

def process_currency_column(excel_file_path, output_excel_file_path):
    # Read the Excel file into a DataFrame
    df = pd.read_excel(excel_file_path)

    # Assuming the penultimate column is of type string and contains currency symbols
    penultimate_col_name = df.columns[-2]

    # Get the penultimate column values as a list of strings
    currency_strings = df[penultimate_col_name].astype(str).tolist()

    # Convert currency strings to float using OpenCL
    context = cl.create_some_context()
    queue = cl.CommandQueue(context)

    # Prepare the data for OpenCL (convert strings to byte arrays)
    max_len = max(len(s) for s in currency_strings)
    currency_bytes = np.array([s.encode('utf-8') + b' ' * (max_len - len(s)) for s in currency_strings], dtype=np.uint8)
    num_entries = len(currency_strings)

    # Create a buffer for input and output data
    mf = cl.mem_flags
    input_buffer = cl.Buffer(context, mf.READ_ONLY | mf.COPY_HOST_PTR, hostbuf=currency_bytes)
    output_buffer = cl.Buffer(context, mf.WRITE_ONLY, currency_bytes.nbytes // max_len * 4)

    # OpenCL kernel that strips currency symbol and converts to float
    kernel_code = """
    __kernel void convert_currency(__constant uchar *input, __global float *output, int max_len) {
        int gid = get_global_id(0);
        float result = 0.0f;
        int sign = 1;
        int decimal_point_encountered = 0;
        int decimal_places = 0;

        // Determine if the number is negative
        if (input[gid * max_len] == '-') {
            sign = -1;
            gid++;
        }

        // Skip currency symbol, assuming it's at position 0 or 1
        if (gid % max_len < 1 || (input[(gid % max_len) + gid * max_len] < '0' || input[(gid % max_len) + gid * max_len] > '9')) {
            gid++;
        }

        // Process each character of the string
        for (int i = gid * max_len; i < (gid + 1) * max_len; i++) {
            uchar c = input[i];
            if (c >= '0' && c <= '9') {
                result = result * 10.0f + (c - '0');
                if (decimal_point_encountered) {
                    decimal_places++;
                }
            } else if (c == '.') {
                decimal_point_encountered = 1;
            }
        }

        // Apply the decimal point
        if (decimal_places > 0) {
            result /= pow(10.0f, decimal_places);
        }

        // Apply the sign
        result *= sign;

        // Store the result in the output buffer
        output[gid] = result;
    }
    """

    # Compile the OpenCL kernel
    prg = cl.Program(context, kernel_code).build()

    # Execute the kernel
    prg.convert_currency(queue, (num_entries,), None, input_buffer, output_buffer, np.int32(max_len))

    # Read the results from the output buffer
    results = np.empty(num_entries, dtype=np.float32)
    cl.enqueue_copy(queue, results, output_buffer).wait()

    # Update the DataFrame with the new float values
    df[penultimate_col_name] = results

    # Save the updated DataFrame to a new Excel file
    df.to_excel(output_excel_file_path, index=False)

